urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}
    {#- lastmod reflects the content review date from front matter, not the build date -#}
    {% set lastmod = file.page.meta.get('dateModified') or file.page.meta.get('last_reviewed') %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if lastmod %}{{ lastmod }}{% endif %}

    {%- endif -%}
{% endfor %}
